cardCss:
.card{font-family:"Noto Serif SC","Songti SC","STSong","SimSun",serif;font-size:16px;text-align:left;color:#333;background-color:#ffffff;-webkit-font-smoothing:antialiased;position:relative;overflow:visible;padding:0}
.card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;background:linear-gradient(90deg,#0e7490,#06b6d4);z-index:10}
.opt-radio,.submit-check,.reset-radio{position:absolute;opacity:0;width:0;height:0;pointer-events:none}
.anki-card{max-width:800px;margin:0 auto;padding:28px 32px}
.card-topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}
.subject{font-size:11px;font-weight:700;letter-spacing:2px;color:#0e7490;background:#ecfeff;border:1px solid #67e8f9;padding:2px 10px}
.qtype{font-size:11px;font-weight:700;letter-spacing:2px;color:#0e7490}
.map-node{font-size:12px;color:#888;margin-bottom:12px;padding:6px 12px;border-left:3px solid #67e8f9;background:#ecfeff;border-radius:0 4px 4px 0}
.node-text{color:#155e75}
.primary-chapter{font-size:11px;color:#0e7490;margin-top:2px}
.q-section{margin-bottom:16px}
.q-text{font-size:17px;font-weight:700;line-height:1.7;color:#164e63;white-space:pre-wrap}
.options{display:flex;flex-direction:column;gap:8px;margin-bottom:16px}
.option{display:flex;align-items:flex-start;gap:10px;padding:10px 14px;border:1px solid #e0f2fe;font-size:15px;color:#444;cursor:pointer;transition:all .2s;background:#fff}
.option:hover{border-color:#0e7490;background:#ecfeff}
.opt-badge{flex-shrink:0;width:24px;height:24px;border:1px solid #ddd;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;color:#999}
.opt-text{flex:1;padding-top:1px}
.opt-mark{color:#059669;font-weight:700;font-size:14px;margin-left:4px}
.card-divider{border:none;border-top:1px solid #cffafe;margin:14px 0}
.answer-section{display:flex;align-items:center;gap:10px;margin-bottom:8px}
.answer-label{font-size:12px;font-weight:700;color:#0e7490;letter-spacing:2px}
.answer-value{font-size:20px;font-weight:700;color:#155e75}
.analysis-section{margin-top:10px}
.analysis-title{font-size:12px;font-weight:700;color:#0e7490;letter-spacing:2px;margin-bottom:8px}
.analysis-content{font-size:14px;color:#555;line-height:1.8}
.analysis-content b{color:#0e7490}
.analysis-content .key-point{color:#0e7490;font-weight:700}
.analysis-content .law-ref{color:#155e75;font-weight:700;border-bottom:2px solid #0e7490}
.extension{margin-top:10px;padding:10px 14px;border-left:3px solid #67e8f9;background:#ecfeff;font-size:13px;color:#155e75;border-radius:0 4px 4px 0}
.chapter-overview{margin-top:12px;padding:12px 16px;border:1px solid #fef08a;border-left:4px solid #ca8a04;background:#fefce8;font-size:13px;color:#854d0e;line-height:1.8;border-radius:0 6px 6px 0}
.related-chapters{font-size:12px;color:#ca8a04;margin-bottom:4px}
.primary-chapter-back{font-size:12px;color:#ca8a04;margin-bottom:4px}
.mindmap-section{margin-top:8px;font-size:12px;color:#854d0e}
.mindmap-context{font-size:12px;color:#888;line-height:1.6}
.mindmap-chapter{font-weight:700;color:#155e75;margin-bottom:4px}
.mindmap-tree{padding-left:8px}
.mindmap-node{padding:1px 0}
.mindmap-node.active{color:#0e7490;font-weight:700}
.current-tag{font-size:10px;color:#0e7490;background:#ecfeff;padding:1px 6px;border:1px solid #67e8f9;margin-left:4px}
.answer-reveal{display:block}
.quiz-controls{display:flex;gap:10px;margin-top:12px}
.quiz-controls label,.quiz-controls button{display:inline-flex;align-items:center;border:1px solid #0e7490;background:transparent;color:#0e7490;padding:8px 24px;font-size:13px;font-weight:700;cursor:pointer;font-family:inherit;letter-spacing:1px;transition:all .2s}
.quiz-controls label:hover,.quiz-controls button:hover{background:#ecfeff}
.submit-label{display:inline-flex}
.reset-label{display:none;border-color:#eee;color:#999}
/* === User selection (before submit) - teal === */
.option.is-selected{border-color:#0e7490;background:#ecfeff}
.option.is-selected .opt-badge{background:#0e7490;color:#fff;border-color:#0e7490}
/* === After submit: correct = green === */
.quiz-form.is-submitted .anki-card .option[data-correct="true"]{border-color:#059669;background:#d1fae5}
.quiz-form.is-submitted .anki-card .option[data-correct="true"] .opt-badge{background:#059669;color:#fff;border-color:#059669}
.quiz-form.is-submitted .anki-card .option[data-correct="true"] .opt-text{font-weight:600;color:#065f46}
/* === After submit: wrong selection = red === */
.quiz-form.is-submitted .anki-card .option.is-selected:not([data-correct="true"]){border-color:#dc2626;background:#fef2f2}
.quiz-form.is-submitted .anki-card .option.is-selected:not([data-correct="true"]) .opt-badge{background:#dc2626;color:#fff;border-color:#dc2626}
.quiz-form.is-submitted .anki-card .option.is-selected:not([data-correct="true"]) .opt-text{color:#991b1b}
/* === After submit: unselected wrong = dimmed === */
.quiz-form.is-submitted .anki-card .option:not([data-correct="true"]):not(.is-selected){opacity:.4}
.quiz-form.is-submitted .anki-card .options .option{cursor:default}
.quiz-form.is-submitted .anki-card .option:hover{border-color:#e0f2fe;background:#fff}
.quiz-form.is-submitted .anki-card .option[data-correct="true"]:hover{border-color:#059669;background:#d1fae5}
/* === Answer reveal === */
.quiz-form.is-submitted .anki-card .answer-reveal{display:block}
/* === Show/hide controls === */
.quiz-form.is-submitted .anki-card .submit-label{display:none}
.quiz-form.is-submitted .anki-card .reset-label{display:inline-flex}
/* === Back side: always show correct === */
.card-back .option[data-correct="true"]{border-color:#059669;background:#d1fae5}
.card-back .option[data-correct="true"] .opt-badge{background:#059669;color:#fff;border-color:#059669}
.card-back .option[data-correct="true"] .opt-text{font-weight:600;color:#065f46}
.card-back .option:not([data-correct="true"]){opacity:.5}
.card-back .option{cursor:default}
.card-back .option:hover{border-color:#e0f2fe;background:#fff}
.card-back .option[data-correct="true"]:hover{border-color:#059669;background:#d1fae5}
.quiz-form{margin:0;padding:0}.reset-label{font-family:inherit}
/* AnkiMobile repair: natural document scrolling and explicit selection state. */
html { height:auto; min-height:100%; overflow-y:auto; }
body.card { height:auto; min-height:100%; max-height:none; overflow:visible; }
.anki-card { box-sizing:border-box; overflow:visible; overflow-wrap:break-word; }
.card::before { pointer-events:none; }
.option { min-height:44px; box-sizing:border-box; -webkit-tap-highlight-color:transparent; }
.option .opt-text { min-width:0; }
.option { display:block; }
.option-summary { display:flex; align-items:flex-start; gap:10px; list-style:none; cursor:pointer; }
.option-summary::-webkit-details-marker,.submit-label::-webkit-details-marker { display:none; }
.option[open] { border-color:#0e7490; background:#ecfeff; }
.option[open] .opt-badge { background:#0e7490; color:#fff; border-color:#0e7490; }
.option[open] .opt-text { color:#155e75; font-weight:600; }
.submit-label { list-style:none; border:1px solid #0e7490; border-radius:4px; padding:12px 20px; font-family:inherit; font-size:14px; font-weight:700; color:#0e7490; cursor:pointer; }
.answer-body { padding-top:4px; }
.answer-reveal { margin-top:12px; }
.card-back .option[data-correct="true"] .opt-badge { background:#059669; border-color:#059669; color:#fff; }
.opt-radio:checked ~ .opt-badge { background:#0e7490; color:#fff; border-color:#0e7490; }
.opt-radio:checked ~ .opt-text { color:#155e75; font-weight:600; }
.submit-check:checked ~ .anki-card .option:not([data-correct="true"]) .opt-radio:checked ~ .opt-badge { background:#dc2626; color:#fff; border-color:#dc2626; }
.submit-check:checked ~ .anki-card .option:not([data-correct="true"]) .opt-radio:checked ~ .opt-text { color:#991b1b; }
.submit-check:checked ~ .anki-card .option:not([data-correct="true"]) { opacity:1; }
.submit-check:checked ~ .anki-card .options { pointer-events:none; }
.quiz-controls { flex-wrap:wrap; }
.quiz-controls label,.quiz-controls button { min-height:44px; box-sizing:border-box; border-radius:4px; -webkit-appearance:none; appearance:none; }
.quiz-controls .reset-label { display:none; }
.quiz-form.is-submitted .quiz-controls .reset-label { display:inline-flex; }
.quiz-form .submit-check:checked ~ .anki-card .quiz-controls .reset-label { display:inline-flex; }
.quiz-form .submit-check:checked ~ .anki-card .quiz-controls .submit-label { display:none; }
.quiz-form.is-submitted .quiz-controls .submit-label { display:none; }
.quiz-form.is-submitted .answer-reveal { display:block; }
.answer-reveal[hidden] { display:none !important; }
.quiz-status { color:#155e75; line-height:1.7; font-size:14px; margin-top:10px; }
.quiz-status:empty { display:none; }
.option:focus-visible, .quiz-controls button:focus-visible { outline:2px solid #0e7490; outline-offset:2px; }
@media (hover:none) { .option:hover { border-color:#e0f2fe; background:#fff; } .option.is-selected:hover { border-color:#0e7490; background:#ecfeff; } }
@media (max-width:600px) {
  .anki-card { padding:20px 16px 36px; }
  .card-topbar { gap:8px; align-items:flex-start; }
  .qtype { text-align:right; line-height:1.6; }
  .option { padding:12px 10px; }
  .q-text { font-size:17px; }
  .analysis-content { font-size:16px; }
}

.source-pages{margin-top:8px}.source-page{margin:0 0 12px}.source-page img{display:block;max-width:100%;height:auto;margin:8px auto;border:1px solid #e2e8f0;box-sizing:border-box;background:white}
.source-caption,.source-meta{font-size:11px;color:#64748b;line-height:1.6;margin:6px 0}
.source-original,.ocr-text{margin-top:12px;padding:10px 12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:4px}
.source-original summary,.ocr-text summary{cursor:pointer;color:#0e7490;font-size:13px;min-height:24px}
.source-original img{max-width:100%;height:auto}.ocr-text div{white-space:pre-wrap;font-size:14px;line-height:1.85;margin-top:12px;color:#475569}
.answer-section{flex-wrap:wrap}.material-question img{display:block;max-width:100%;height:auto}
.card-back details.option .option-summary{pointer-events:none}.card-back .opt-radio{display:none}
.source-number{font-size:12px;color:#64748b;display:block;margin-bottom:10px}

.anki-audio, .anki-video { display: block; width: 100%; max-width: 100%; margin: 0.5rem 0; }
.anki-media-missing { display: block; margin: 0.35rem 0; color: #9f1239; font-size: 0.875rem; }
.anki-math-source,
.anki-math-rendered {
  display: inline-block;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  vertical-align: middle;
  -webkit-overflow-scrolling: touch;
}
.anki-math-source {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  white-space: pre-wrap;
}
.anki-math-source[data-anki-math="display"],
.anki-math-rendered[data-anki-math="display"] {
  display: block;
  margin: 0.75rem 0;
  text-align: center;
}
.anki-math-rendered math {
  max-width: 100%;
}
@media (max-width: 767px) {
  .anki-math-source,
  .anki-math-rendered {
    width: 100%;
    max-width: 100%;
    text-align: left;
  }
}
